const listHighlights = `-- name: ListHighlights :many
SELECT id, user_id, title, cover_url, sort_order, created_at, updated_at
FROM highlights WHERE user_id = $1 ORDER BY sort_order
`

func (q *Queries) ListHighlights(ctx context.Context, userID int64) ([]Highlight, error) {
	rows, err := q.db.Query(ctx, listHighlights, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Highlight
	for rows.Next() {
		var i Highlight
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Title,
			&i.CoverUrl,
			&i.SortOrder,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

